#!/usr/bin/env node
/**
 * Generates packages/api-client/src/database.generated.ts from the local Supabase schema.
 * Requires local Supabase (`pnpm db:start`) and applied migrations (`pnpm db:reset`).
 */
import { execSync } from 'node:child_process';
import { writeFileSync } from 'node:fs';
import { dirname, join } from 'node:path';
import { fileURLToPath } from 'node:url';

const rootDir = join(dirname(fileURLToPath(import.meta.url)), '..');
const outputPath = join(rootDir, 'packages/api-client/src/database.generated.ts');

const GENERATED_HEADER = `/**
 * THIS FILE IS AUTO-GENERATED — DO NOT EDIT.
 *
 * Generated by: pnpm db:types
 * Source: local Supabase schema (supabase gen types typescript --local)
 *
 * Re-generate after migration changes:
 *   pnpm db:reset && pnpm db:types
 */
`;

function main() {
  let types;
  try {
    types = execSync('pnpm exec supabase gen types typescript --local', {
      cwd: rootDir,
      encoding: 'utf8',
      stdio: ['pipe', 'pipe', 'pipe'],
    });
  } catch (error) {
    const message = error instanceof Error ? error.message : String(error);
    console.error(
      '\n[db:types] Failed to generate database types.\n' +
        'Ensure Docker is running, then:\n' +
        '  pnpm db:start\n' +
        '  pnpm db:reset\n' +
        '  pnpm db:types\n',
    );
    console.error(message);
    process.exit(1);
  }

  const body = types.startsWith('/**') ? types : `${GENERATED_HEADER}\n${types}`;
  writeFileSync(outputPath, body, 'utf8');

  const typesBoundaryPath = join(rootDir, 'packages/api-client/src/database.types.ts');
  writeFileSync(
    typesBoundaryPath,
    `/**
 * Re-exports Supabase-generated schema types from database.generated.ts.
 * Updated automatically by: pnpm db:types
 */
export type { Database, Json, Tables, TablesInsert, TablesUpdate, Enums } from './database.generated';
`,
    'utf8',
  );

  const indexPath = join(rootDir, 'packages/api-client/src/index.ts');
  writeFileSync(
    indexPath,
    `export * from './contracts';
export type { Database, Enums, Json, Tables, TablesInsert, TablesUpdate } from './database.types';
`,
    'utf8',
  );

  console.log(`[db:types] Wrote ${outputPath}`);
}

main();
